import{_ as t,o as s,c as a,a0 as i}from"./chunks/framework.ysVzM4be.js";const k=JSON.parse('{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source, and how to extend the workflow template.","frontmatter":{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source, and how to extend the workflow template."},"headers":[],"relativePath":"getting-started/minimal-config.md","filePath":"getting-started/minimal-config.md"}'),n={name:"getting-started/minimal-config.md"};function o(l,e,d,h,r,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="minimal-config" tabindex="-1">Minimal Config <a class="header-anchor" href="#minimal-config" aria-label="Permalink to &quot;Minimal Config&quot;">​</a></h1><h2 id="the-config-file" tabindex="-1">The Config file <a class="header-anchor" href="#the-config-file" aria-label="Permalink to &quot;The Config file&quot;">​</a></h2><p>The config lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/my-little-software-factory/config.toml</span></span></code></pre></div><p>or at the path the <code>--config</code> flag names:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.toml</span></span></code></pre></div><p>The state file lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.local/state/my-little-software-factory/state.sqlite</span></span></code></pre></div><p>or at the path <code>$XDG_STATE_HOME/my-little-software-factory/state.sqlite</code> when the environment sets it, or at the path the <code>state-file</code> key names when the config sets one.</p><p>The shipped Default configuration carries a working control plane and the parts it cannot know about your machine: no ticket sources, no repository mappings, and no <code>state-file</code> key. Everything else is on: the <code>pi</code>, <code>codex</code>, and <code>claude</code> agent types, the four workflow task types, the three security task types, the task rules of the label workflow plus one rule per security source kind, and one <code>consult</code> Consultation type that passes your input straight through. The <a href="./../configuration/#key-reference">configuration key reference</a> names every key, its default, and what it does.</p><h2 id="add-a-ticket-source" tabindex="-1">Add a ticket source <a class="header-anchor" href="#add-a-ticket-source" aria-label="Permalink to &quot;Add a ticket source&quot;">​</a></h2><p>The Default configuration holds a commented-out source block where you add your own. Unmark it and edit the <code>repositories</code> list to your <code>owner/name</code> values:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refresh-interval-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repositories = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/other&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The <code>name</code> is what the interface shows. The <code>kind</code> is <code>github-issues</code> or <code>github-pull-requests</code>, or one of the security feed kinds <code>github-security-advisories</code>, <code>github-dependabot-alerts</code>, and <code>github-secret-scanning-alerts</code>: the three kinds read the repository security tab, each item appears as one ticket, and the shipped task rules already route each kind to its resolve task type. The security feed kinds take no <code>filter</code>. The <code>refresh-interval-seconds</code> sets how often the control plane refreshes the source. The source reads the labels on each ticket; <a href="./../development/labels.html">the ticket labels</a> name what each label means to the control plane.</p><p>Repository checkout paths live in the <code>repos</code> table, one key per <code>owner/name</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;owner/name&quot; = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/src/name&quot;</span></span></code></pre></div><h2 id="extend-the-workflow-template" tabindex="-1">Extend the workflow template <a class="header-anchor" href="#extend-the-workflow-template" aria-label="Permalink to &quot;Extend the workflow template&quot;">​</a></h2><p>The task types and task rules of the Default configuration form the workflow template, and the file marks them as meant to be extended. The template carries the four task types <code>implement</code>, <code>review</code>, <code>rework</code>, and <code>merge</code>, plus the three security task types <code>resolve-security-advisory</code>, <code>resolve-dependabot-alert</code>, and <code>resolve-secret-scanning-alert</code>, and the rules of the label workflow:</p><table tabindex="0"><thead><tr><th>Rule</th><th>When</th><th>Task type</th></tr></thead><tbody><tr><td>1</td><td>A pull request carries the <code>needs-work</code> label.</td><td><code>rework</code></td></tr><tr><td>2</td><td>A pull request carries the <code>ready-for-review</code> label.</td><td><code>review</code></td></tr><tr><td>3</td><td>A pull request carries the <code>ready-to-ship</code> label.</td><td><code>merge</code></td></tr><tr><td>4</td><td>A ticket comes from a <code>github-security-advisories</code> source.</td><td><code>resolve-security-advisory</code></td></tr><tr><td>5</td><td>A ticket comes from a <code>github-dependabot-alerts</code> source.</td><td><code>resolve-dependabot-alert</code></td></tr><tr><td>6</td><td>A ticket comes from a <code>github-secret-scanning-alerts</code> source.</td><td><code>resolve-secret-scanning-alert</code></td></tr></tbody></table><p>Add your own task type with a <code>[task-types.&lt;name&gt;]</code> table. The <code>template</code> carries the prompt body, and the <code>{placeholders}</code> name the ticket facts the control plane fills in. Add a rule that routes a ticket to it:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My prompt for {title}.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task-type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-type&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">when</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source-kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-pull-request&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">labels-any = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The rules run in file order, and the first match wins. A ticket no rule matches takes the <code>default-task-type</code>.</p>`,22)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
